<?php
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';  // Check if user is authenticated and has proper role
session_start();
if (!isset($_SESSION['user_id'])) {  http_response_code(401);  echo json_encode(['error' => 'Unauthorized']);  exit;
}  $u = current_user();
$role = $u['role'] ?? 'staff';
$roleKey = function_exists('role_key') ? role_key($role) : strtolower(trim((string)$role));  if (!in_array($roleKey, ['superadmin', 'admin', 'developer'])) {  http_response_code(403);  echo json_encode(['error' => 'Access denied']);  exit;
}  header('Content-Type: application/json');  try {  // Only allow POST method  if ($_SERVER['REQUEST_METHOD'] !== 'POST') {  http_response_code(405);  echo json_encode(['error' => 'Method not allowed']);  exit;  }  $optimization_results = [  'tables_optimized' => [],  'indexes_rebuilt' => [],  'space_saved' => 0,  'errors' => [],  'total_time' => 0  ];  $start_time = microtime(true);  // Get all tables  $stmt = $pdo->query("SHOW TABLES");  $tables = [];  while ($row = $stmt->fetch(PDO::FETCH_NUM)) {  $tables[] = $row[0];  }  foreach ($tables as $table) {  try {  // Get table size before optimization  $stmt = $pdo->prepare("  SELECT  data_length + index_length AS size_before  FROM information_schema.tables  WHERE table_schema = DATABASE() AND table_name = ?  ");  $stmt->execute([$table]);  $size_before = $stmt->fetchColumn() ?: 0;  // Optimize table  $pdo->exec("OPTIMIZE TABLE `$table`");  $optimization_results['tables_optimized'][] = $table;  // Get table size after optimization  $stmt->execute([$table]);  $size_after = $stmt->fetchColumn() ?: 0;  $space_saved = $size_before - $size_after;  if ($space_saved > 0) {  $optimization_results['space_saved'] += $space_saved;  }  } catch (Exception $e) {  $optimization_results['errors'][] = "Table $table: " . $e->getMessage();  }  }  // Rebuild indexes if needed  try {  $stmt = $pdo->query("SELECT DISTINCT table_name FROM information_schema.statistics WHERE table_schema = DATABASE()");  while ($row = $stmt->fetch(PDO::FETCH_ASSOC)) {  $table = $row['table_name'];  try {  $pdo->exec("ANALYZE TABLE `$table`");  $optimization_results['indexes_rebuilt'][] = $table;  } catch (Exception $e) {  $optimization_results['errors'][] = "Index on $table: " . $e->getMessage();  }  }  } catch (Exception $e) {  $optimization_results['errors'][] = "Index rebuild: " . $e->getMessage();  }  $optimization_results['total_time'] = round(microtime(true) - $start_time, 2);  $optimization_results['space_saved_mb'] = round($optimization_results['space_saved'] / 1024 / 1024, 2);  // Log the optimization  try {  $stmt = $pdo->prepare("  INSERT INTO system_maintenance_log (maintenance_type, description, status, performed_by, duration_seconds, details)  VALUES (?, ?, ?, ?, ?, ?)  ");  $stmt->execute([  'optimization',  'Database optimization completed',  'completed',  $_SESSION['user_id'],  $optimization_results['total_time'],  json_encode([  'tables_optimized' => count($optimization_results['tables_optimized']),  'indexes_rebuilt' => count($optimization_results['indexes_rebuilt']),  'space_saved_mb' => $optimization_results['space_saved_mb'],  'errors' => count($optimization_results['errors'])  ])  ]);  } catch (Exception $e) {  $optimization_results['errors'][] = "Logging: " . $e->getMessage();  }  // Update cache status  try {  $stmt = $pdo->prepare("  INSERT INTO system_configuration (config_key, config_value)  VALUES ('last_optimization', ?)  ON DUPLICATE KEY UPDATE config_value = VALUES(config_value)  ");  $stmt->execute([date('Y-m-d H:i:s')]);  } catch (Exception $e) {  $optimization_results['errors'][] = "Config update: " . $e->getMessage();  }  echo json_encode([  'success' => true,  'message' => 'Database optimization completed successfully',  'data' => $optimization_results  ]);  } catch (Exception $e) {  error_log("Optimize Database API Error: " . $e->getMessage());  http_response_code(500);  echo json_encode([  'success' => false,  'error' => 'Database optimization failed: ' . $e->getMessage()  ]);
}
?>
